using System;using System.Linq;using System.Text.Json;using cAlgo.API;using Rizan.Portfolio;
int checks=0;void Check(bool x,string why){checks++;if(!x)throw new Exception(why);}
DateTime start=new(2026,10,12,4,0,0,DateTimeKind.Utc);
TestHost Host(double balance=100000000,double cost=1,bool delay=true){var h=new TestHost{EnableTrading=true,EnableXau=false,EnableEur=false,EnableBtc=true};h.ExpectedAccount=h.Account.Number.ToString();h.Account.Balance=h.Account.Equity=balance;h.PortfolioRiskPercent=20.75;h.FeeFactor=cost;h.Server.TimeInUtc=start;h.CreateEngines();h.Btc!.ReplayStart();h.Symbols.GetSymbol("BTCUSD").Bid=10000;h.Symbols.GetSymbol("BTCUSD").Ask=10005;h.Symbols.GetSymbol("BTCUSD").Leverage=200;if(delay)h.BeforeMarketFill=()=>{h.Server.TimeInUtc=h.Server.TimeInUtc.AddSeconds(2);h.Mark();};return h;}
ResearchCase Profile(int orders=8,double risk=.025,double margin=.1,int seconds=180)=>new(){SafetyFraction=.9,BtcBatchOrders=orders,BtcBatchRisk=risk,BtcBatchMargin=margin,BtcBatchSeconds=seconds,BtcBuyHours=1,BtcSellHours=1};
foreach(int side in new[]{1,-1})foreach(double balance in new[]{5000000d,100000000d})foreach(double cost in new[]{1d,2d})foreach(double margin in new[]{.0001,.1}){
 RP.C=Profile(margin:margin);var h=Host(balance,cost);h.Btc!.Enter(new(start,side,200,10000),start);Check(h.Requests==1,"FIRST_FILL_ON_TIME");Check((h.Server.TimeInUtc-start).TotalSeconds==2,"FIRST_FILL_DELAY_TWO_SECONDS");
 int guard=0;while(h.Btc.ResearchBatchQueued&&guard++<1000){h.Server.TimeInUtc=h.Server.TimeInUtc.AddSeconds(1);h.Btc.Manage(h.Server.TimeInUtc);Check(h.Positions.All(p=>p.VolumeInUnits<=100&&p.StopLoss!=null&&p.TakeProfit!=null),"PER_ORDER_CAP_AND_PROTECTION");Check(h.OpenRisk()<=Math.Min(h.Account.Balance,h.Account.Equity)*.2075+1e-6,"GLOBAL_RISK");Check(h.Account.Margin<=Math.Min(h.Account.Balance,h.Account.Equity)*.5+1e-6,"GLOBAL_MARGIN");}
 Check(guard<1000,"QUEUE_FINITE");Check(h.Requests<=8,"BATCH_COUNT_CAP");Check(!h.Btc.ResearchBatchQueued&&h.Btc.PendingRisk==0&&h.Btc.PendingMargin==0,"RESERVES_RELEASED");Check(h.Positions.Select(p=>p.Label).Distinct().Count()==h.Positions.Count,"UNIQUE_LABELS");Check(h.Positions.Sum(p=>p.VolumeInUnits*(Math.Abs(p.EntryPrice-p.StopLoss!.Value)+p.EntryPrice*.0012))<=Math.Min(balance,h.Account.Equity)*.025+1e-6,"BTC_RISK_BUDGET");Check(h.Account.Margin<=Math.Min(balance,h.Account.Equity)*margin+1e-6,"BTC_MARGIN_BUDGET");
 h.Server.TimeInUtc=start.AddHours(1).AddSeconds(2);h.Btc.Manage(h.Server.TimeInUtc);Check(h.Positions.Count==0&&h.History.Count==h.Requests,"EXPIRY_CLOSES_ALL_NO_LOST_FEES");
 Check(Math.Abs(h.Account.Balance-balance-h.History.Sum(t=>t.NetProfit))<1e-5,"CASH_RECONCILIATION");
}
RP.C=Profile();var early=Host(100);early.Btc!.Enter(new(start,1,20,10000),start);Check(early.Requests==1&&!early.Btc.ResearchBatchQueued,"SMALL_WALLET_LEGACY_SINGLE_ORDER");
RP.C=Profile();var duplicate=Host();duplicate.Btc!.Enter(new(start,1,200,10000),start);int requests=duplicate.Requests;duplicate.Btc.Enter(new(start,1,200,10000),duplicate.Server.TimeInUtc);Check(duplicate.Requests==requests,"DUPLICATE_SIGNAL_NO_IMMEDIATE_ORDER");
RP.C=Profile();var stopped=Host();stopped.Btc!.Enter(new(start,1,200,10000),start);stopped.ClosePosition(stopped.Positions.Single());stopped.Server.TimeInUtc=stopped.Server.TimeInUtc.AddSeconds(1);stopped.Btc.Manage(stopped.Server.TimeInUtc);Check(stopped.Requests==1&&!stopped.Btc.ResearchBatchQueued,"STOP_OR_TP_CANCELS_QUEUE");
RP.C=Profile(seconds:2);var deadline=Host();deadline.Btc!.Enter(new(start,1,200,10000),start);deadline.Server.TimeInUtc=deadline.Server.TimeInUtc.AddSeconds(1);deadline.Btc.Manage(deadline.Server.TimeInUtc);Check(deadline.Requests==1&&!deadline.Btc.ResearchBatchQueued,"LATE_CHILD_CANCELLED");
RP.C=Profile();var late=Host();late.Server.TimeInUtc=start.AddSeconds(6);late.Btc!.Enter(new(start,1,200,10000),late.Server.TimeInUtc);Check(late.Requests==0,"INITIAL_DEADLINE_UNCHANGED");
RP.C=Profile();var off=Host();off.Btc!.Enter(new(start,1,200,10000),start);off.EnableTrading=false;off.Server.TimeInUtc=off.Server.TimeInUtc.AddSeconds(2);off.Btc.Manage(off.Server.TimeInUtc);Check(off.Requests==1,"OFF_BLOCKS_CHILD_ORDERS");
RP.C=Profile();var friday=Host();friday.Server.TimeInUtc=new DateTime(2026,10,16,21,30,0,DateTimeKind.Utc);friday.Btc!.Enter(new(friday.Server.TimeInUtc,1,200,10000),friday.Server.TimeInUtc);Check(friday.Requests==0,"FRIDAY_ENTRY_BLOCK");
RP.C=Profile();var native=new TestHost{EnableTrading=true,EnableXau=false,EnableEur=false,EnableBtc=true};native.Server.TimeInUtc=start;native.CreateEngines();native.Btc!.OnStart();native.Btc.Enter(new(start,1,200,10000),start);Check(native.Requests==0&&!native.Btc.RecoveryReady,"NATIVE_UNVERIFIED_BRIDGE_BLOCKS_ORDERS");
foreach(int side in new[]{1,-1}){RP.C=Profile(orders:128);var large=Host();large.Btc!.Enter(new(start,side,200,10000),start);int guard=0;while(large.Btc.ResearchBatchQueued&&guard++<1000){large.Server.TimeInUtc=large.Server.TimeInUtc.AddSeconds(1);large.Btc.Manage(large.Server.TimeInUtc);}Check(large.Requests==60&&!large.Btc.ResearchBatchQueued,"MAX_PROFILE_OBEYS_180S_BROKER_TIMING");Check(large.Positions.All(p=>p.VolumeInUnits<=100)&&large.OpenRisk()<=Math.Min(large.Account.Balance,large.Account.Equity)*.2075,"MAX_PROFILE_PROTECTED_AND_CAPPED");}
var initialFunding=new Position{Label="RZBTC8500283|"+start.Ticks,EntryTime=start.AddSeconds(2)};var childFunding=new Position{Label="RZBTC8500283|"+start.Ticks+"|B2",EntryTime=start.AddSeconds(92)};
Check(ResearchAccounting.FundingStart(initialFunding)==start,"LEGACY_FUNDING_BASELINE_UNCHANGED");Check(ResearchAccounting.FundingStart(childFunding)==childFunding.EntryTime,"CHILD_FUNDING_ACTUAL_FILL");
Console.WriteLine(JsonSerializer.Serialize(new{Pass=true,Checks=checks,FakeBrokerOnly=true,LiveOrders=0,BothSides=true,PerOrderBtcCap=100}));
